import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for 2D average pooling (float32)
# ----------------------------------------------------------------------
avgpool_kernel = """
__global__ void avgpool_kernel(const float* input, const int kernel_size, const int stride,
                                const int padding, float* output, int batch_size, int channels,
                                int out_h, int out_w) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < out_h * out_w) {
        int local_h = idx / out_w;
        int local_w = idx % out_w;

        float sum = 0.0f;
        for (int ky = -padding; ky <= kernel_size - 1; ++ky) {
            int ny = local_h + ky;
            if (ny < 0 || ny >= x.size(2)) continue;
            for (int kx = -padding; kx <= kernel_size - 1; ++kx) {
                int nx = local_w + kx;
                if (nx < 0 || nx >= x.size(3)) continue;
                sum += input[(blockIdx.y * channels + ... )];
            }
        }
        output[idx] = sum / (kernel_size * kernel_size);
    }
}
"""

# ----------------------------------------------------------------------
# C++ wrapper for the custom average pooling function
# ----------------------------------------------------------------------
cpp_source = """
torch::Tensor avg_pool2d_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    // Convert input to float
    auto x_f = x.to(torch::kFloat);
    // Compute output spatial dimensions
    int out_h = (x_f.size(2) + 2 * padding - stride) / stride + 1;
    int out_w = (x_f.size(3) + 2 * padding - stride) / stride + 1;

    // Allocate output tensor: (batch, channels, out_h, out_w)
    auto out_shape = x.size(0).unsqueeze(1).unsqueeze(2).reshape(-1, x_f.size(1), out_h, out_w);
    auto out_tensor = torch::empty(out_shape, torch::kFloat, device=x.device);

    // Launch kernel
    const int block_size = 256;
    avgpool_kernel<<<out_h * out_w, block_size>>> (x.data_ptr<float>(), kernel_size, stride, padding,
                                                    out_tensor.data_ptr<float>(), x.size(0), x.size(1),
                                                    out_h, out_w);

    return out_tensor;
}
"""

# Load the inline function
avg_pool2d_cuda = load_inline(
    name="avg_pool2d_cuda",
    cpp_sources=cpp_source,
    cuda_sources=avgpool_kernel,
    functions=["avg_pool2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int = 11, stride: int = None, padding: int = 0):
        super(ModelNew, self).__init__()
        # If stride is None we let the underlying function use its default (kernel_size)
        self.avg_pool = avg_pool2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.avg_pool(x)
